-- FOUNDATION MIGRATION — REVIEW AND APPLY MANUALLY. Never executed by the application.
-- Designed for a project with no public application tables; it never deletes Auth users.
create extension if not exists citext;
create extension if not exists pgcrypto;

create table public.departments (id uuid primary key default gen_random_uuid(), name text not null unique check (char_length(name) between 2 and 120), code text not null unique check (code ~ '^[A-Z0-9_]{2,32}$'), created_at timestamptz not null default now());
create table public.wards (id uuid primary key default gen_random_uuid(), ward_number integer not null unique check (ward_number > 0), ward_name text not null check (char_length(trim(ward_name)) between 2 and 120), is_active boolean not null default true, created_at timestamptz not null default now());
-- Uses only the supplied pilot designation; no locality name is invented.
insert into public.wards (ward_number, ward_name) values (6, 'Ward 06') on conflict (ward_number) do nothing;

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null check (char_length(trim(full_name)) between 2 and 100), username citext not null unique check (username ~ '^[A-Za-z0-9_]{3,30}$'), phone text not null check (phone ~ '^\+[1-9][0-9]{7,14}$'), residential_address text not null check (char_length(trim(residential_address)) between 10 and 300), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.staff_profiles (user_id uuid primary key references auth.users(id) on delete cascade, department_id uuid not null references public.departments(id) on delete restrict, mobile_e164 text not null unique check (mobile_e164 ~ '^[+]91[6-9][0-9]{9}$'), role text not null check (role in ('staff','supervisor','administrator')), active boolean not null default true, approved boolean not null default false, force_password_change boolean not null default true, provisioned_at timestamptz not null default now());
create table public.staff_ward_assignments (staff_user_id uuid not null references public.staff_profiles(user_id) on delete cascade, ward_id uuid not null references public.wards(id) on delete restrict, assigned_at timestamptz not null default now(), primary key (staff_user_id, ward_id));
create table public.complaints (id uuid primary key default gen_random_uuid(), citizen_id uuid not null references public.profiles(id) on delete restrict, department_id uuid references public.departments(id) on delete set null, ward_id uuid not null references public.wards(id) on delete restrict, title text not null check (char_length(trim(title)) between 5 and 160), description text not null check (char_length(trim(description)) between 10 and 5000), category text not null check (char_length(trim(category)) between 2 and 80), severity smallint not null default 1 check (severity between 1 and 5), status text not null default 'submitted' check (status in ('submitted','acknowledged','in_progress','resolved','closed','rejected')), latitude numeric(9,6), longitude numeric(9,6), photo_path text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check ((latitude is null and longitude is null) or (latitude between -90 and 90 and longitude between -180 and 180)), check (photo_path is null or photo_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[^/]+$'));
create table public.complaint_assignments (id uuid primary key default gen_random_uuid(), complaint_id uuid not null references public.complaints(id) on delete cascade, staff_user_id uuid not null references public.staff_profiles(user_id) on delete restrict, assigned_by uuid not null references public.staff_profiles(user_id) on delete restrict, assigned_at timestamptz not null default now(), unassigned_at timestamptz, unique (complaint_id, staff_user_id, assigned_at));
create table public.complaint_status_history (id uuid primary key default gen_random_uuid(), complaint_id uuid not null references public.complaints(id) on delete cascade, previous_status text, new_status text not null check (new_status in ('submitted','acknowledged','in_progress','resolved','closed','rejected')), note text check (char_length(note) <= 2000), changed_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now());
create index complaints_citizen_idx on public.complaints(citizen_id); create index complaints_department_ward_idx on public.complaints(department_id, ward_id); create index staff_ward_assignments_ward_idx on public.staff_ward_assignments(ward_id, staff_user_id); create index assignment_staff_active_idx on public.complaint_assignments(staff_user_id) where unassigned_at is null; create index history_complaint_idx on public.complaint_status_history(complaint_id, created_at desc);

create function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at = now(); return new; end; $$;
create trigger profiles_updated before update on public.profiles for each row execute procedure public.set_updated_at(); create trigger complaints_updated before update on public.complaints for each row execute procedure public.set_updated_at();

-- Exceptions abort auth.users insertion, so signUp receives an error and no partial account/profile commits.
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$
declare v_full_name text := nullif(trim(new.raw_user_meta_data ->> 'full_name'), ''); v_username text := lower(nullif(trim(new.raw_user_meta_data ->> 'username'), '')); v_phone text := nullif(trim(new.raw_user_meta_data ->> 'phone'), ''); v_address text := nullif(trim(new.raw_user_meta_data ->> 'residential_address'), '');
begin
  if v_full_name is null or char_length(v_full_name) not between 2 and 100 then raise exception using errcode='22023', message='Registration metadata has an invalid full name'; end if;
  if v_username is null or v_username !~ '^[A-Za-z0-9_]{3,30}$' then raise exception using errcode='22023', message='Registration metadata has an invalid username'; end if;
  if v_phone is null or v_phone !~ '^\+[1-9][0-9]{7,14}$' then raise exception using errcode='22023', message='Registration metadata has an invalid phone number'; end if;
  if v_address is null or char_length(v_address) not between 10 and 300 then raise exception using errcode='22023', message='Registration metadata has an invalid residential address'; end if;
  if exists (select 1 from public.profiles where username=v_username) then raise exception using errcode='23505', message='Username is already in use'; end if;
  insert into public.profiles(id,full_name,username,phone,residential_address) values(new.id,v_full_name,v_username,v_phone,v_address);
  return new;
end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

create function public.staff_authorized_for_complaint(target_department uuid, target_ward uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists (select 1 from public.staff_profiles sp join public.staff_ward_assignments swa on swa.staff_user_id=sp.user_id join public.wards w on w.id=swa.ward_id and w.is_active=true where sp.user_id=auth.uid() and sp.active=true and sp.approved=true and sp.force_password_change=false and sp.department_id=target_department and swa.ward_id=target_ward) $$;
create function public.validate_assignment() returns trigger language plpgsql set search_path='' as $$ declare complaint_department uuid; complaint_ward uuid; assignee_department uuid; assigner_department uuid; assigner_role text; begin select department_id,ward_id into complaint_department,complaint_ward from public.complaints where id=new.complaint_id; select department_id into assignee_department from public.staff_profiles where user_id=new.staff_user_id and active=true and approved=true; select department_id,role into assigner_department,assigner_role from public.staff_profiles where user_id=new.assigned_by and active=true and approved=true; if complaint_department is null or assignee_department is distinct from complaint_department or assigner_department is distinct from complaint_department or assigner_role not in ('supervisor','administrator') or not exists(select 1 from public.staff_ward_assignments where staff_user_id=new.staff_user_id and ward_id=complaint_ward) or not exists(select 1 from public.staff_ward_assignments where staff_user_id=new.assigned_by and ward_id=complaint_ward) then raise exception 'invalid complaint assignment'; end if; return new; end; $$;
create trigger assignment_is_authorised before insert on public.complaint_assignments for each row execute procedure public.validate_assignment();
revoke all on function public.staff_authorized_for_complaint(uuid,uuid) from public,anon; grant execute on function public.staff_authorized_for_complaint(uuid,uuid) to authenticated;

alter table public.departments enable row level security; alter table public.wards enable row level security; alter table public.profiles enable row level security; alter table public.staff_profiles enable row level security; alter table public.staff_ward_assignments enable row level security; alter table public.complaints enable row level security; alter table public.complaint_assignments enable row level security; alter table public.complaint_status_history enable row level security;
grant select on public.departments,public.wards to authenticated; grant select,update on public.profiles to authenticated; grant select on public.staff_profiles,public.staff_ward_assignments,public.complaint_assignments,public.complaint_status_history to authenticated; grant select,insert,update on public.complaints to authenticated;
create policy "read departments" on public.departments for select to authenticated using(true); create policy "read active wards" on public.wards for select to authenticated using(is_active=true); create policy "read own profile" on public.profiles for select to authenticated using(id=auth.uid()); create policy "update own profile" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid()); create policy "read own staff record" on public.staff_profiles for select to authenticated using(user_id=auth.uid()); create policy "read own ward assignments" on public.staff_ward_assignments for select to authenticated using(staff_user_id=auth.uid());
create policy "citizen reads own complaints" on public.complaints for select to authenticated using(citizen_id=auth.uid()); create policy "staff reads authorised complaints" on public.complaints for select to authenticated using(public.staff_authorized_for_complaint(department_id,ward_id)); create policy "citizen creates own complaint" on public.complaints for insert to authenticated with check(citizen_id=auth.uid() and department_id is null); create policy "citizen updates own unassigned complaint" on public.complaints for update to authenticated using(citizen_id=auth.uid() and status='submitted' and department_id is null) with check(citizen_id=auth.uid() and status='submitted' and department_id is null); create policy "staff updates authorised complaint" on public.complaints for update to authenticated using(public.staff_authorized_for_complaint(department_id,ward_id)) with check(public.staff_authorized_for_complaint(department_id,ward_id));
create policy "staff reads authorised assignments" on public.complaint_assignments for select to authenticated using(staff_user_id=auth.uid() or exists(select 1 from public.complaints c where c.id=complaint_id and public.staff_authorized_for_complaint(c.department_id,c.ward_id))); create policy "citizen or authorised staff reads history" on public.complaint_status_history for select to authenticated using(exists(select 1 from public.complaints c where c.id=complaint_id and (c.citizen_id=auth.uid() or public.staff_authorized_for_complaint(c.department_id,c.ward_id))));
-- No browser policy permits staff provisioning, ward assignment, complaint assignment, or history mutation.

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('complaint-photos','complaint-photos',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "upload own complaint photo" on storage.objects for insert to authenticated with check(bucket_id='complaint-photos' and (storage.foldername(name))[1]=(select auth.uid()::text) and array_length(storage.foldername(name),1)=2); create policy "read authorised complaint photo" on storage.objects for select to authenticated using(bucket_id='complaint-photos' and ((storage.foldername(name))[1]=(select auth.uid()::text) or exists(select 1 from public.complaints c where c.photo_path=name and public.staff_authorized_for_complaint(c.department_id,c.ward_id)))); create policy "delete own unlinked complaint photo" on storage.objects for delete to authenticated using(bucket_id='complaint-photos' and (storage.foldername(name))[1]=(select auth.uid()::text) and not exists(select 1 from public.complaints where photo_path=name));
